// GradientBackground — "HANZO Ember Bloom", made with the 21st.dev Gradient
// Builder and exported as live CSS (the builder's own Copy-CSS background,
// plus its soften-blur and grain passes). Zero dependencies: one <div> that
// fills its parent. Drop it behind your content:
// <div className="relative h-96"><GradientBackground className="absolute inset-0" /></div>
// Remix the source recipe (colors, mode, finish) in the editor:
// https://21st.dev/community/gradients/editor?from=c0bf78d8-fca7-48db-a409-946a64f5d0fc
export function GradientBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        containerType: "size",
      }}
    >
      <div
        style={{
          position: "absolute",
        inset: 0,
        backgroundColor: "#262626",
        backgroundImage:
          "radial-gradient(circle at 65.58% 46.03%, rgba(10, 10, 10, 1) 0%, rgba(10, 10, 10, 0.844) 10.28%, rgba(10, 10, 10, 0.5) 20.55%, rgba(10, 10, 10, 0.156) 30.83%, rgba(10, 10, 10, 0) 41.1%), radial-gradient(circle at 28.38% 73.04%, rgba(220, 40, 40, 1) 0%, rgba(220, 40, 40, 0.844) 13.78%, rgba(220, 40, 40, 0.5) 27.55%, rgba(220, 40, 40, 0.156) 41.33%, rgba(220, 40, 40, 0) 55.1%), radial-gradient(circle at 52.62% 18.32%, rgba(129, 29, 29, 1) 0%, rgba(129, 29, 29, 0.844) 16.4%, rgba(129, 29, 29, 0.5) 32.8%, rgba(129, 29, 29, 0.156) 49.2%, rgba(129, 29, 29, 0) 65.6%), radial-gradient(circle at 79.22% 84.38%, rgba(38, 38, 38, 1) 0%, rgba(38, 38, 38, 0.844) 19.02%, rgba(38, 38, 38, 0.5) 38.05%, rgba(38, 38, 38, 0.156) 57.07%, rgba(38, 38, 38, 0) 76.1%)",
        }}
      />
    </div>
  )
}

